    if ((body_a == NULL) || (body_b == NULL) || (inertial_a == NULL) || (inertial_b == NULL) || (mismatch_rad == NULL)) {
        return ADCS_E_NULL;
    }

    // 2. Check for non-finite components in input vectors
    if (!adcs_is_finite_vec3(body_a) || !adcs_is_finite_vec3(body_b) || 
        !adcs_is_finite_vec3(inertial_a) || !adcs_is_finite_vec3(inertial_b)) {
        return ADCS_E_NOT_FINITE;
    }

    // 3. Check norms for degeneracy (too small or overflow/non-finite)
    double norm_a_body = adcs_vec3_norm(body_a);
    double norm_b_body = adcs_vec3_norm(body_b);
    double norm_a_inertial = adcs_vec3_norm(inertial_a);
    double norm_b_inertial = adcs_vec3_norm(inertial_b);

    if ((!isfinite(norm_a_body)) || (!isfinite(norm_b_body)) || 
        (!isfinite(norm_a_inertial)) || (!isfinite(norm_b_inertial)) ||
        (norm_a_body <= ADCS_EPS_NORM) || (norm_b_body <= ADCS_EPS_NORM) ||
        (norm_a_inertial <= ADCS_EPS_NORM) || (norm_b_inertial <= ADCS_EPS_NORM)) {
        return ADCS_E_DEGENERATE;
    }

    // 4. Normalize inertial vectors and compute angle
    adcs_vec3_t u_a_inertial, u_b_inertial;
    adcs_vec3_normalize(inertial_a, ADCS_EPS_NORM, &u_a_inertial);
    adcs_vec3_normalize(inertial_b, ADCS_EPS_NORM, &u_b_inertial);

    double dot_inertial = adcs_vec3_dot(&u_a_inertial, &u_b_inertial);
    double clamped_dot_inertial = ADCS_CLAMP(dot_inertial, -1.0, 1.0);
    double angle_inertial = acos(clamped_dot_inertial);

    // 5. Normalize body vectors and compute angle
    adcs_vec3_t u_a_body, u_b_body;
    adcs_vec3_normalize(body_a, ADCS_EPS_NORM, &u_a_body);
    adcs_vec3_normalize(body_b, ADCS_EPS_NORM, &u_b_body);

    double dot_body = adcs_vec3_dot(&u_a_body, &u_b_body);
    double clamped_dot_body = ADCS_CLAMP(dot_body, -1.0, 1.0);
    double angle_body = acos(clamped_dot_body);

    // 6. Compute mismatch as absolute difference
    double mismatch = fabs(angle_inertial - angle_body);

    // 7. Output result
    *mismatch_rad = mismatch;
    return ADCS_OK;
}

