    if (adcs_vec3_normalize(body_a, ADCS_EPS_NORM, &u_ba) != ADCS_OK) {
        *mismatch_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    // Process Body B
    n = adcs_vec3_norm(body_b);
    if (!isfinite(n) || n <= ADCS_EPS_NORM) {
        *mismatch_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }
    if (adcs_vec3_normalize(body_b, ADCS_EPS_NORM, &u_bb) != ADCS_OK) {
        *mismatch_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    double dot_inertial = adcs_vec3_dot(&u_ia, &u_ib);
    double cos_inertial = ADCS_CLAMP(dot_inertial, -1.0, 1.0);
    double angle_inertial = acos(cos_inertial);

    double dot_body = adcs_vec3_dot(&u_ba, &u_bb);
    double cos_body = ADCS_CLAMP(dot_body, -1.0, 1.0);
    double angle_body = acos(cos_body);

    *mismatch_rad = fabs(angle_inertial - angle_body);

    return ADCS_OK;
}
